const pptxgen = require("pptxgenjs");
const slideConfig = { type: 'content', index: 4, title: 'Retention Gap' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Slide title
  slide.addText("AI-First Apps Show 14% Median Retention vs. 51% for Incumbents", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Chart data for Incumbent apps (left side)
  const incumbentData = [
    { name: "WhatsApp", value: 85 },
    { name: "Instagram", value: 64 },
    { name: "YouTube", value: 64 },
    { name: "TikTok", value: 60 },
    { name: "Snapchat", value: 51 },
    { name: "Median", value: 51 }
  ];

  // Chart data for AI-First companies (right side)
  const aiFirstData = [
    { name: "Character.ai", value: 41 },
    { name: "Runway", value: 27 },
    { name: "Remini", value: 14 },
    { name: "ChatGPT", value: 14 },
    { name: "Lensa", value: 12 },
    { name: "Median", value: 14 }
  ];

  // Left chart - Incumbent apps
  slide.addChart(pres.ChartType.bar, {
    x: 0.3, y: 1.0, w: 4.3, h: 4.0,
    chartColors: [theme.accent],
    barDir: "bar",
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelFontSize: 9,
    dataLabelColor: theme.primary,
    catAxisTitle: "",
    valAxisTitle: "",
    valAxisMaxVal: 100,
    valAxisMinVal: 0,
    showLegend: false,
    valGridLine: { color: theme.light, size: 0.5 },
    catGridLine: { style: "none" },
    chartData: [
      { name: "Retention", labels: incumbentData.map(d => d.name), values: incumbentData.map(d => d.value) }
    ],
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: theme.secondary,
    valAxisLabelFontSize: 8
  });

  // Right chart - AI-First companies
  slide.addChart(pres.ChartType.bar, {
    x: 4.8, y: 1.0, w: 4.0, h: 4.0,
    chartColors: [theme.secondary],
    barDir: "bar",
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelFontSize: 9,
    dataLabelColor: theme.primary,
    catAxisTitle: "",
    valAxisTitle: "",
    valAxisMaxVal: 100,
    valAxisMinVal: 0,
    showLegend: false,
    valGridLine: { color: theme.light, size: 0.5 },
    catGridLine: { style: "none" },
    chartData: [
      { name: "Retention", labels: aiFirstData.map(d => d.name), values: aiFirstData.map(d => d.value) }
    ],
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: theme.secondary,
    valAxisLabelFontSize: 8
  });

  // Add median labels with bold styling
  slide.addText("Median: 51%", {
    x: 3.6, y: 3.65, w: 1.0, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  slide.addText("Median: 14%", {
    x: 8.0, y: 3.65, w: 1.0, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Group labels
  slide.addText("Incumbent Apps", {
    x: 0.3, y: 5.0, w: 4.3, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: theme.accent, bold: true, align: "center"
  });

  slide.addText("AI-First Companies", {
    x: 4.8, y: 5.0, w: 4.0, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: theme.secondary, bold: true, align: "center"
  });

  // Page number badge
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: theme.light, bold: true,
    fill: { color: theme.primary },
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

